<?php
$e = static fn (mixed $value): string => App\Core\View::e($value);
$base = App\Core\Config::url('/prestacao/campeonatos/' . $championshipId);
$query = static fn (array $values): string => http_build_query(array_filter($values, static fn (mixed $value): bool => $value !== '' && $value !== null));
$selected = static fn (string $key, mixed $value): string => (string) ($filters[$key] ?? '') === (string) $value ? ' selected' : '';
?>
<section class="page-stack">
    <div class="section-heading"><div><p class="eyebrow">Relatório oficial</p><h1>Prestação de contas</h1><p class="muted">Acompanhe partidas aprovadas, atletas, documentos e evidências autorizadas do campeonato.</p></div><a class="button secondary" href="<?= $e(App\Core\Config::url('/prestacao')) ?>">Voltar</a></div>
    <?php if (!empty($message)): ?><p class="success" role="status"><?= $e($message) ?></p><?php endif; ?>
    <section class="metric-grid"><?php foreach ($summary as $label => $value): ?><article class="metric-card"><span><?= $e(str_replace('_', ' ', $label)) ?></span><strong><?= (int) $value ?></strong></article><?php endforeach; ?></section>
    <article class="panel"><div class="panel-heading"><div><h2>Filtrar registros</h2><p class="muted">Revise partidas e evidências por fase, equipe, local ou dia de evento.</p></div></div><form method="get" action="<?= $e($base) ?>" class="filter-grid">
        <label>Fase<select name="phase_id"><option value="">Todas</option><?php foreach ($filterOptions['phases'] as $option): ?><option value="<?= (int) $option['id'] ?>"<?= $selected('phase_id', $option['id']) ?>><?= $e($option['name']) ?></option><?php endforeach; ?></select></label>
        <label>Grupo<select name="group_id"><option value="">Todos</option><?php foreach ($filterOptions['groups'] as $option): ?><option value="<?= (int) $option['id'] ?>"<?= $selected('group_id', $option['id']) ?>><?= $e($option['name']) ?></option><?php endforeach; ?></select></label>
        <label>Rodada<select name="round_id"><option value="">Todas</option><?php foreach ($filterOptions['rounds'] as $option): ?><option value="<?= (int) $option['id'] ?>"<?= $selected('round_id', $option['id']) ?>><?= $e($option['round_label']) ?></option><?php endforeach; ?></select></label>
        <label>Equipe<select name="team_id"><option value="">Todas</option><?php foreach ($filterOptions['teams'] as $option): ?><option value="<?= (int) $option['id'] ?>"<?= $selected('team_id', $option['id']) ?>><?= $e($option['name']) ?></option><?php endforeach; ?></select></label>
        <label>Local<select name="venue_id"><option value="">Todos</option><?php foreach ($filterOptions['venues'] as $option): ?><option value="<?= (int) $option['id'] ?>"<?= $selected('venue_id', $option['id']) ?>><?= $e($option['name']) ?><?= !empty($option['city']) ? ' - ' . $e($option['city']) : '' ?></option><?php endforeach; ?></select></label>
        <label>Cidade<select name="city"><option value="">Todas</option><?php foreach ($filterOptions['cities'] as $option): ?><option value="<?= $e($option['name']) ?>"<?= $selected('city', $option['name']) ?>><?= $e($option['name']) ?></option><?php endforeach; ?></select></label>
        <label>Dia do evento<select name="event_day_id"><option value="">Todos</option><?php foreach ($filterOptions['event_days'] as $option): ?><option value="<?= (int) $option['id'] ?>"<?= $selected('event_day_id', $option['id']) ?>><?= $e($option['event_date']) ?> - <?= $e($option['name']) ?></option><?php endforeach; ?></select></label>
        <label>De<input type="date" name="from" value="<?= $e($filters['from'] ?? '') ?>"></label><label>Até<input type="date" name="to" value="<?= $e($filters['to'] ?? '') ?>"></label>
        <label>Situação documental<select name="document_status"><option value="">Todas</option><option value="completa"<?= $selected('document_status', 'completa') ?>>Completa</option><option value="pendente"<?= $selected('document_status', 'pendente') ?>>Pendente</option></select></label><button type="submit">Aplicar filtros</button>
    </form></article>
    <article class="panel"><div class="panel-heading"><div><h2>Exportar dados</h2><p class="muted">Os downloads respeitam sua autorização e ficam registrados nos logs.</p></div></div><div class="quick-actions"><?php foreach (['csv' => 'CSV', 'xlsx' => 'Excel', 'pdf' => 'PDF', 'zip' => 'Pacote completo ZIP', 'evidencias' => 'Evidências CSV', 'evidencias-xlsx' => 'Evidências Excel'] as $format => $label): ?><a class="button" href="<?= $e($base . '/exportar/' . $format . ($query($filters) ? '?' . $query($filters) : '')) ?>"><?= $e($label) ?></a><?php endforeach; ?></div></article>
    <article class="panel"><div class="panel-heading"><div><p class="eyebrow">Atletas e documentos</p><h2>Documentação dos atletas</h2><p class="muted">Baixe os dados dos atletas com inscrição aprovada e, quando necessário, o pacote privado com os documentos autorizados.</p></div></div><div class="quick-actions"><a class="button" href="<?= $e($base . '/exportar/atletas-documentos') ?>">Baixar planilha de atletas</a><a class="button secondary" href="<?= $e($base . '/exportar/atletas-documentos-zip') ?>">Baixar planilha e documentos</a></div><p class="muted">Documentos pessoais não aparecem no portal público.</p></article>
    <article class="panel"><div class="panel-heading"><div><p class="eyebrow">Registro por evento</p><h2>Dias de evento</h2><p class="muted">Evidências do dia podem reunir fotos e documentos de várias partidas e locais.</p></div></div><?php if (empty($filterOptions['event_days'])): ?><p class="muted">Nenhum dia de evento foi cadastrado.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>Data</th><th>Nome</th><th>Local</th><th>Cidade</th></tr></thead><tbody><?php foreach ($filterOptions['event_days'] as $day): ?><tr><td><?= $e($day['event_date']) ?></td><td><?= $e($day['name']) ?></td><td><?= $e($day['venue_name'] ?: 'Vários locais') ?></td><td><?= $e($day['city'] ?: '-') ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></article>
    <article class="panel"><h2>Partidas aprovadas</h2><div class="table-wrap"><table><thead><tr><th>Partida</th><th>Fase / grupo</th><th>Rodada</th><th>Data</th><th>Local</th><th>Publicação</th><th>Documentação</th><th></th></tr></thead><tbody><?php foreach ($matches as $match): ?><tr><td><?= $e($match['mandante']) ?> x <?= $e($match['visitante']) ?></td><td><?= $e($match['fase']) ?> / <?= $e($match['grupo']) ?></td><td><?= $e($match['rodada_label'] ?? ('Rodada ' . (int) $match['round_number'])) ?></td><td><?= $e($match['match_date']) ?> <?= $e($match['match_time']) ?></td><td><?= $e($match['venue_name'] ?? '-') ?><?= !empty($match['venue_city']) ? ' - ' . $e($match['venue_city']) : '' ?></td><td><?= $e($match['publication_status'] ?: 'interna') ?></td><td><?= $e($match['document_status']) ?></td><td><a class="button secondary" href="<?= $e($base . '/partidas/' . $match['id']) ?>">Ver detalhe</a></td></tr><?php endforeach; ?><?php if ($matches === []): ?><tr><td colspan="8">Nenhuma partida aprovada corresponde aos filtros.</td></tr><?php endif; ?></tbody></table></div></article>
</section>
